```js
// config.js: env var > .env file > default; fail fast when invalid.
import "dotenv/config";
const cfg = {
  host: process.env.DB_HOST,
  port: Number(process.env.DB_PORT ?? 5432),
  password: process.env.DB_PASSWORD,   // from .env locally, from CI secrets in prod.
};
const missing = ["host", "password"].filter((k) => !cfg[k]);
if (missing.length) throw new Error(`Missing config: ${missing.join(", ")}`);
if (!Number.isInteger(cfg.port)) throw new Error("DB_PORT must be a number");
export default cfg;
```

